// Los sponsors de las cabeceras: los mismos de Nadamos por la milanga (JAC y San Cayetano) y Tachuela Racing.
// En cada carrera salen dos al azar en la salida y dos en la llegada.
function sponsorImg(src) { const i = new Image(); i.src = src; return i; }
